using System;
using System.Linq;
using System.Collections.Generic;
using System.Globalization;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.SceneManagement;
using HarmonyLib;

partial class ModEditorWindow : MonoBehaviour {
 internal static ModEditorWindow Instance;internal bool Open;
 Transform selected;string search="",assetSearch="",projectName="MyMod",label="",price="0",duration="0";int componentIndex,actionIndex,tab;
 string[] position=new string[3],rotation=new string[3],scale=new string[3];bool active,disabled;float previousTime,next;bool ownLock;RaycastClick[] clicks;bool[] clickStates;UnityEngine.EventSystems.BaseRaycaster[] raycasters;bool[] raycasterStates;
 Vector2 treeScroll,inspectorScroll,assetScroll;HashSet<int> expanded=new HashSet<int>();List<Transform> roots=new List<Transform>();UnityEngine.Object[] assets=new UnityEngine.Object[0];
 Camera viewCamera;RenderTexture preview;GUIStyle heading,small,selectedStyle;Texture2D panel;string[] tabs={"Transform","Взаимодействия","Компоненты"};
 void Awake(){Instance=this;ModEditorStore.Initialize();projectName=ModEditorStore.Project.name;}
 void Update(){FlyCamera();if(Input.GetKeyDown(KeyCode.F8))Toggle();if(Time.realtimeSinceStartup<next)return;next=Time.realtimeSinceStartup+1;EnsureMenuButton();if(Open)RefreshRoots();}
 internal static void Tick(){ModEditorStore.Apply();}
 void EnsureMenuButton(){var button=Resources.FindObjectsOfTypeAll<Button>().FirstOrDefault(b=>FloorAdmin.PathOf(b.transform)=="OverlayGUI/StartMenu/Back/StartGame");if(button==null||button.transform.parent.Find("ModEditorButton")!=null)return;var copy=Instantiate(button,button.transform.parent);copy.name="ModEditorButton";foreach(var behaviour in copy.GetComponentsInChildren<MonoBehaviour>(true))if(!(behaviour is UnityEngine.EventSystems.UIBehaviour)&&!(behaviour is LocalizedText))behaviour.enabled=false;copy.onClick=new Button.ButtonClickedEvent();copy.onClick.AddListener(Toggle);foreach(var text in copy.GetComponentsInChildren<LocalizedText>(true))text.text="Mod Editor";var rect=copy.GetComponent<RectTransform>();if(rect!=null)rect.anchoredPosition+=Vector2.right*Mathf.Min(340,Screen.width*.3f);copy.gameObject.SetActive(true);copy.interactable=true;}
 internal void Toggle(){if(Open)Close();else Show();}
 internal void Show(){if(Open)return;Open=true;previousTime=Time.timeScale;Time.timeScale=0;var player=PlayerActionsSystem.Instance;if(player!=null){player.Navigation.Lock=true;ownLock=true;}clicks=Resources.FindObjectsOfTypeAll<RaycastClick>().Where(c=>c.gameObject.scene.IsValid()).ToArray();clickStates=clicks.Select(c=>c.enabled).ToArray();foreach(var click in clicks)click.enabled=false;raycasters=Resources.FindObjectsOfTypeAll<UnityEngine.EventSystems.BaseRaycaster>().Where(r=>r.gameObject.scene.IsValid()).ToArray();raycasterStates=raycasters.Select(r=>r.enabled).ToArray();foreach(var raycaster in raycasters)raycaster.enabled=false;RefreshRoots();if(Camera.main!=null){var holder=new GameObject("ModEditorPreviewCamera");viewCamera=holder.AddComponent<Camera>();viewCamera.CopyFrom(Camera.main);viewCamera.enabled=false;viewCamera.transform.SetPositionAndRotation(Camera.main.transform.position,Camera.main.transform.rotation);preview=new RenderTexture(960,540,24);viewCamera.targetTexture=preview;}FloorAdmin.Log("EDITOR opened");}
 internal void Close(){if(!Open)return;if(sceneLoading){ModEditorStore.Status="Дождитесь загрузки сцены";return;}CancelTransformDrag();ReleaseEditorScene();Open=false;Time.timeScale=previousTime;if(ownLock&&PlayerActionsSystem.Instance!=null)PlayerActionsSystem.Instance.Navigation.Lock=false;ownLock=false;if(clicks!=null)for(int i=0;i<clicks.Length;i++)if(clicks[i]!=null)clicks[i].enabled=clickStates[i];if(raycasters!=null)for(int i=0;i<raycasters.Length;i++)if(raycasters[i]!=null)raycasters[i].enabled=raycasterStates[i];if(viewCamera!=null)Destroy(viewCamera.gameObject);if(preview!=null){preview.Release();Destroy(preview);}FloorAdmin.Log("EDITOR testing mode");}
 void OnDestroy(){Close();}
 void RefreshRoots(){roots.Clear();for(int i=0;i<SceneManager.sceneCount;i++){var scene=SceneManager.GetSceneAt(i);if(scene.isLoaded)roots.AddRange(scene.GetRootGameObjects().Where(g=>g.name!="ModEditorPreviewCamera").Select(g=>g.transform));}}
 void Select(Transform value){CancelTransformDrag();var placed=value==null?null:value.GetComponentInParent<EditorPlacedObject>();selected=placed==null?value:placed.transform;componentIndex=actionIndex=0;LoadFields();}
 void LoadFields(){if(selected==null)return;ReadVector(position,selected.localPosition);ReadVector(rotation,selected.localEulerAngles);ReadVector(scale,selected.localScale);active=selected.gameObject.activeSelf;ReadAction();}
 static void ReadVector(string[] fields,Vector3 value){for(int i=0;i<3;i++)fields[i]=value[i].ToString("0.###",CultureInfo.InvariantCulture);}
 ActionsList CurrentList(){if(selected==null)return null;return selected.GetComponents<ActionsList>().ElementAtOrDefault(componentIndex);}
 void ReadAction(){var list=CurrentList();if(list==null)return;disabled=list.Disabled;var action=list.Actions==null?null:list.Actions.ElementAtOrDefault(actionIndex);if(action==null)return;label=action.Name;price=action.Price.ToString();duration=action.Duration.ToString(CultureInfo.InvariantCulture);}
 void Styles(){if(panel!=null)return;panel=new Texture2D(1,1);panel.SetPixel(0,0,new Color(.09f,.11f,.14f));panel.Apply();heading=new GUIStyle(GUI.skin.label){fontSize=18,fontStyle=FontStyle.Bold};small=new GUIStyle(GUI.skin.label){fontSize=12,wordWrap=true};selectedStyle=new GUIStyle(GUI.skin.button);selectedStyle.normal.textColor=new Color(.45f,.85f,1);}
 void OnGUI(){if(!Open)return;Styles();GUI.depth=-1000;GUI.DrawTexture(new Rect(0,0,Screen.width,Screen.height),panel);float left=240,right=310,center=Screen.width-left-right-16;float body=Screen.height-88,assetHeight=Mathf.Min(200,body*.32f);Rect view=new Rect(left+8,88,center,body-assetHeight-52);
  GUILayout.BeginArea(new Rect(10,8,Screen.width-20,40));GUILayout.BeginHorizontal();GUILayout.Label("BEHOLDER 2  /  MOD EDITOR",heading,GUILayout.Width(310));projectName=GUILayout.TextField(projectName,GUILayout.Width(140));if(GUILayout.Button("Новый"))Try(()=>{ModEditorStore.New(projectName);});if(GUILayout.Button("Загрузить"))Try(()=>{ModEditorStore.Load(projectName);LoadFields();});if(GUILayout.Button("Сохранить"))Try(()=>{ModEditorStore.Project.name=projectName;ModEditorStore.Save();});if(GUILayout.Button("Экспорт"))Try(ModEditorStore.Export);if(GUILayout.Button("Отмена"))Try(()=>{ModEditorStore.Undo();LoadFields();});if(GUILayout.Button("Повтор"))Try(()=>{ModEditorStore.Redo();LoadFields();});if(GUILayout.Button("Проверить / F8"))Close();GUILayout.EndHorizontal();GUILayout.EndArea();
  GUILayout.BeginArea(new Rect(8,50,left-8,body),GUI.skin.box);DrawSceneChooser();GUILayout.Label("Scene Hierarchy",heading);search=GUILayout.TextField(search);treeScroll=GUILayout.BeginScrollView(treeScroll);foreach(var root in roots.ToArray())if(root!=null&&(string.IsNullOrEmpty(editScene)||root.gameObject.scene.name==editScene))Tree(root,0);GUILayout.EndScrollView();GUILayout.EndArea();
  GUILayout.BeginArea(new Rect(left+8,50,center,34));GUILayout.BeginHorizontal();DrawTransformToolbar();if(GUILayout.Button("В кадр"))Frame();if(GUILayout.Button("↶"))Orbit(-15);if(GUILayout.Button("↷"))Orbit(15);GUILayout.EndHorizontal();GUILayout.EndArea();
  if(viewCamera!=null&&preview!=null){if(Event.current.type==EventType.Repaint)viewCamera.Render();GUI.DrawTexture(view,preview,ScaleMode.ScaleToFit);DrawTransformHandles(view);NavigateScene(view);if(view.Contains(Event.current.mousePosition)){if(Event.current.type==EventType.ScrollWheel){viewCamera.transform.position+=viewCamera.transform.forward*Event.current.delta.y*.3f;Event.current.Use();}if(Event.current.type==EventType.MouseDown&&Event.current.button==0){float ratio=preview.width/(float)preview.height;float width=Mathf.Min(view.width,view.height*ratio),height=width/ratio;var actual=new Rect(view.center.x-width/2,view.center.y-height/2,width,height);var p=Event.current.mousePosition;if(actual.Contains(p)){var ray=viewCamera.ViewportPointToRay(new Vector3((p.x-actual.x)/actual.width,1-(p.y-actual.y)/actual.height,0));RaycastHit hit;if(Physics.Raycast(ray,out hit,1000,viewCamera.cullingMask))Select(hit.transform);}Event.current.Use();}}}else GUI.Label(view,"Начните новую игру, затем откройте редактор клавишей F8.",small);
  DrawPropLibrary(new Rect(left+8,Screen.height-assetHeight-38,center,assetHeight));
  GUILayout.BeginArea(new Rect(Screen.width-right,50,right-8,body),GUI.skin.box);GUILayout.Label("Inspector",heading);inspectorScroll=GUILayout.BeginScrollView(inspectorScroll);if(selected==null)GUILayout.Label("Выберите объект в дереве или в сцене.");else Inspector();GUILayout.EndScrollView();GUILayout.EndArea();
  GUI.Label(new Rect(10,Screen.height-30,Screen.width-20,26),(ModEditorStore.Dirty?"● Не сохранено  |  ":"")+ModEditorStore.Status,small);
 }
 void Tree(Transform t,int depth){if(search.Length>0){if(t.name.IndexOf(search,StringComparison.OrdinalIgnoreCase)>=0)if(GUILayout.Button(FloorAdmin.PathOf(t),t==selected?selectedStyle:GUI.skin.button))Select(t);foreach(Transform child in t)Tree(child,depth+1);return;}GUILayout.BeginHorizontal();GUILayout.Space(Mathf.Min(depth,12)*12);bool has=t.childCount>0;bool open=expanded.Contains(t.GetInstanceID());if(has&&GUILayout.Button(open?"−":"+",GUILayout.Width(22))){if(open)expanded.Remove(t.GetInstanceID());else expanded.Add(t.GetInstanceID());}if(GUILayout.Button((t.gameObject.activeSelf?"":"○ ")+t.name,t==selected?selectedStyle:GUI.skin.button))Select(t);GUILayout.EndHorizontal();if(has&&open)foreach(Transform child in t)Tree(child,depth+1);}
 void Inspector(){GUILayout.Label(selected.name,heading);GUILayout.Label(selected.gameObject.scene.name+" / "+FloorAdmin.PathOf(selected),small);tab=GUILayout.SelectionGrid(tab,tabs,1,GUILayout.Width(265));if(tab==0){active=GUILayout.Toggle(active,"Объект активен");VectorFields("Позиция (local)",position);VectorFields("Поворот",rotation);VectorFields("Масштаб",scale);if(GUILayout.Button("Применить Transform"))Try(()=>{var p=ModEditorStore.ReadTransform(selected);var v=Parse(position);var r=Parse(rotation);var s=Parse(scale);if(s.x<=0||s.y<=0||s.z<=0)throw new Exception("Масштаб должен быть положительным");p.x=v.x;p.y=v.y;p.z=v.z;p.rx=r.x;p.ry=r.y;p.rz=r.z;p.sx=s.x;p.sy=s.y;p.sz=s.z;p.active=active;ModEditorStore.Change(p);});}
  else if(tab==1){var components=selected.GetComponents<ActionsList>();if(components.Length==0)GUILayout.Label("На этом объекте нет ActionsList. Выберите узел взаимодействий в дереве.",small);else{if(components.Length>1){int nextIndex=GUILayout.SelectionGrid(componentIndex,components.Select((x,i)=>"ActionsList "+i).ToArray(),1);if(nextIndex!=componentIndex){componentIndex=nextIndex;actionIndex=0;ReadAction();}}var list=CurrentList();var actions=list.Actions??new PlayerAction[0];for(int i=0;i<actions.Length;i++)if(actions[i]!=null&&GUILayout.Button(actions[i].Name,i==actionIndex?selectedStyle:GUI.skin.button)){actionIndex=i;ReadAction();}var action=actions.ElementAtOrDefault(actionIndex);if(action!=null){GUILayout.Label("Подпись команды");label=GUILayout.TextField(label);GUILayout.Label("Цена ("+action.PriceType+")");price=GUILayout.TextField(price);GUILayout.Label("Время действия");duration=GUILayout.TextField(duration);disabled=GUILayout.Toggle(disabled,"Отключить список взаимодействий");GUILayout.Label("Сохраняются исходные условия и сценарий команды. Редактируются подпись, цена и время.",small);if(GUILayout.Button("Применить взаимодействие"))Try(()=>{int amount;float minutes;if(!int.TryParse(price,out amount)||amount<0||!float.TryParse(duration.Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out minutes)||float.IsNaN(minutes)||float.IsInfinity(minutes)||minutes<0)throw new Exception("Цена и время должны быть неотрицательными числами");ModEditorStore.Change(new EditorChange{scene=selected.gameObject.scene.name,path=ModEditorStore.Key(selected),kind="interaction",component=componentIndex,action=action.name,label=label,price=amount,duration=minutes,disabled=disabled});});}}}
  else{foreach(var component in selected.GetComponents<Component>())if(component!=null)GUILayout.Label(component.GetType().FullName,small);GUILayout.Label("Произвольный вызов методов и изменение скрытых полей отключены.",small);}
  GUILayout.Space(12);if(selected.GetComponent<EditorPlacedObject>()!=null&&GUILayout.Button("Удалить размещённый предмет")){var key=selected.GetComponent<EditorPlacedObject>().id;ModEditorStore.RemoveSpawn(key);selected=null;return;}if(GUILayout.Button("Копировать информацию")){GUIUtility.systemCopyBuffer=ModEditorStore.Describe(selected);ModEditorStore.Status="Информация об объекте скопирована";}
 }
 static void VectorFields(string title,string[] values){GUILayout.Label(title);GUILayout.BeginHorizontal();for(int i=0;i<3;i++)values[i]=GUILayout.TextField(values[i],GUILayout.Width(78));GUILayout.EndHorizontal();}
 static Vector3 Parse(string[] values){var result=Vector3.zero;for(int i=0;i<3;i++){float number;if(!float.TryParse(values[i].Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out number)||float.IsNaN(number)||float.IsInfinity(number))throw new Exception("Некорректные координаты");result[i]=number;}return result;}
 void Frame(){if(viewCamera==null||selected==null)return;var renderers=selected.GetComponentsInChildren<Renderer>();var bounds=selected.GetComponent<Collider>()==null?new Bounds(selected.position,Vector3.one):selected.GetComponent<Collider>().bounds;if(renderers.Length>0){bounds=renderers[0].bounds;foreach(var r in renderers.Skip(1))bounds.Encapsulate(r.bounds);}viewCamera.transform.position=bounds.center-viewCamera.transform.forward*Mathf.Max(2,bounds.extents.magnitude*2.5f);}
 void Orbit(float degrees){if(viewCamera==null)return;var center=selected==null?viewCamera.transform.position+viewCamera.transform.forward*5:selected.position;viewCamera.transform.RotateAround(center,Vector3.up,degrees);viewCamera.transform.LookAt(center);}
 void Try(Action action){try{action();}catch(Exception e){ModEditorStore.Status=e.Message;FloorAdmin.Log("EDITOR "+e);}}
}





